   108→
   109→```typescript
   110→// apps/desktop/src/navigation/route-compiler.ts
   111→
   112→export interface CompiledPattern {
   113→  pattern: string;
   114→  regex: RegExp;
   115→  paramNames: string[];
   116→  restParam: string | null;
   117→  build: (params: Record<string, string>) => string;
   118→  constantSegmentCount: number;
   119→}
   120→
   121→/**
   122→ * Compile a URL pattern into a regex matcher and URL builder.
   123→ * Patterns use :param for single segments and :param+ for rest (multi-segment).
   124→ * All compiled regexes are anchored with ^ and $.
   125→ */
   126→export function compilePattern(pattern: string): CompiledPattern {
   127→  const paramNames: string[] = [];
   128→  let restParam: string | null = null;
   129→  let constantSegmentCount = 0;
   130→
   131→  const segments = pattern.split("/").filter(Boolean);
   132→  const regexParts: string[] = [];
   133→  const buildParts: Array<{ type: "const"; value: string } | { type: "param"; name: string; rest: boolean }> = [];
   134→
   135→  for (const segment of segments) {
   136→    if (segment.startsWith(":")) {
   137→      const isRest = segment.endsWith("+");
   138→      const name = isRest ? segment.slice(1, -1) : segment.slice(1);
   139→      paramNames.push(name);
   140→      if (isRest) {
   141→        restParam = name;
   142→        regexParts.push("(.+)");
   143→      } else {
   144→        regexParts.push("([^/]+)");
   145→      }
   146→      buildParts.push({ type: "param", name, rest: isRest });
   147→    } else {
   148→      constantSegmentCount++;
   149→      regexParts.push(escapeRegex(segment));
   150→      buildParts.push({ type: "const", value: segment });
   151→    }
   152→  }
   153→
   154→  const regex = new RegExp("^\\/" + regexParts.join("\\/") + "$");
   155→
   156→  const build = (params: Record<string, string>): string => {
   157→    const parts = buildParts.map((part) => {
   158→      if (part.type === "const") return part.value;
   159→      const value = params[part.name];
   160→      if (!value && part.rest) {
   161→        throw new Error(`Rest param "${part.name}" must be non-empty for pattern: ${pattern}`);
   162→      }
   163→      // Rest params: keep / unencoded. Single params: encode.
   164→      return part.rest ? value : encodeURIComponent(value);
   165→    });
   166→    return "/" + parts.join("/");
   167→  };
   168→
   169→  return { pattern, regex, paramNames, restParam, build, constantSegmentCount };
   170→}
   171→
   172→function escapeRegex(str: string): string {
   173→  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
   174→}
   175→```
