   639→```typescript
   640→// apps/desktop/src/navigation/breadcrumb-builder.ts
   641→import { registry, humanize } from "./route-registry";
   642→import type { RouteEntry, RouteMatch } from "./route-compiler";
   643→import type { IconData } from "@/types/icon";
   644→
   645→// ─── Types ──────────────────────────────────────────────────────────────────
   646→
   647→export interface NavigateHeaders {
   648→  label?: string;
   649→  icon?: IconData;
   650→  id?: string;
   651→  sourceNodeId?: string;
   652→  parentNodeId?: string;
   653→  meta?: BreadcrumbMeta;
   654→}
   655→
   656→export interface BreadcrumbMeta {
   657→  workspaceId?: string;
   658→  section?: string;
   659→  pageSlug?: string;
   660→  agentId?: string;
   661→  executorType?: string;
   662→  webId?: string;
   663→  url?: string;
   664→  blockId?: string;
   665→}
   666→
   667→export interface BreadcrumbStackItem {
   668→  id: string;
   669→  label: string;
   670→  icon?: IconData;
   671→  pattern?: string;
   672→  href?: string;
   673→  sourceNodeId?: string;
   674→  parentNodeId?: string;
   675→  meta?: BreadcrumbMeta;
   676→}
   677→
   678→// ─── Cold Start Builder ─────────────────────────────────────────────────────
   679→
   680→export function buildColdStartBreadcrumb(url: string, headers?: NavigateHeaders): BreadcrumbStackItem[] {
   681→  const match = registry.match(url);
   682→  if (!match) return [];
   683→
   684→  const chain: BreadcrumbStackItem[] = [];
   685→
   686→  // 1. Path prefix ancestors
   687→  for (const ancestorPattern of deriveAncestorsFromPrefix(match.pattern)) {
   688→    const ancestorEntry = registry.getEntry(ancestorPattern)!;
   689→    const ancestorParams = pickMatchingParams(ancestorPattern, match.params);
   690→    chain.push(buildBreadcrumbItem(ancestorEntry, ancestorPattern, ancestorParams));
   691→  }
   692→
   693→  // 2. Rest param intermediate levels
   694→  const restParam = registry.getRestParam(match.pattern);
   695→  if (restParam && match.params[restParam]?.includes("/")) {
   696→    const segments = match.params[restParam].split("/");
   697→    for (let i = 1; i < segments.length; i++) {
   698→      const prefix = segments.slice(0, i).join("/");
   699→      const lastSegment = segments[i - 1];
   700→      chain.push(buildBreadcrumbItem(
   701→        match.entry,
   702→        match.pattern,
   703→        { ...match.params, [restParam]: prefix },
   704→        { label: humanize(lastSegment) },
   705→      ));
   706→    }
   707→  }
   708→
   709→  // 3. Current node (headers can override label/icon)
   710→  chain.push(buildBreadcrumbItem(match.entry, match.pattern, match.params, headers));
   711→
   712→  return chain;
   713→}
   714→
   715→// ─── Helpers ────────────────────────────────────────────────────────────────
   716→
   717→export function deriveAncestorsFromPrefix(pattern: string): string[] {
   718→  const segments = pattern.split("/").filter(Boolean);
   719→  const ancestors: string[] = [];
   720→
   721→  for (let i = segments.length - 1; i > 0; i--) {
   722→    const candidate = "/" + segments.slice(0, i).join("/");
   723→    if (registry.hasEntry(candidate)) {
   724→      ancestors.unshift(candidate);
   725→    }
   726→  }
   727→  return ancestors;
   728→}
   729→
   730→export function pickMatchingParams(
   731→  targetPattern: string,
   732→  allParams: Record<string, string>,
   733→): Record<string, string> {
   734→  const paramNames = registry.getParamNames(targetPattern);
   735→  const result: Record<string, string> = {};
   736→  for (const name of paramNames) {
   737→    if (allParams[name] !== undefined) {
   738→      result[name] = allParams[name];
   739→    }
   740→  }
   741→  return result;
   742→}
   743→
   744→export function buildBreadcrumbItem(
   745→  entry: RouteEntry,
   746→  pattern: string,
   747→  params: Record<string, string>,
   748→  headers?: NavigateHeaders,
   749→): BreadcrumbStackItem {
   750→  const href = registry.build(pattern, params);
   751→  const icon = headers?.icon ?? (typeof entry.icon === "function" ? entry.icon(params) : entry.icon);
   752→  const title = typeof entry.title === "function" ? entry.title(params) : entry.title;
   753→
   754→  return {
   755→    id: headers?.id ?? href,
   756→    label: headers?.label ?? title,
   757→    icon,
   758→    pattern,
   759→    href,
   760→    sourceNodeId: headers?.sourceNodeId,
   761→    parentNodeId: headers?.parentNodeId,
   762→    meta: headers?.meta,
   763→  };
   764→}
   765→```
