   481→export function urlToLocation(url: string): DesktopLocation | null {
   482→  const parsed = new URL(url, "http://desktop.local");
   483→  const pathname = parsed.pathname;
   484→  const segments = pathname.split("/").filter(Boolean);
   485→  const suffix = { search: parsed.search || undefined, hash: parsed.hash || undefined };
   486→
   487→  if (pathname === "/documents") return { kind: "documents", ...suffix };
   488→  if (pathname === "/devices/pair") return { kind: "device-pair", ...suffix };
   489→  if (pathname === "/publish" || pathname === "/my-packages" || pathname === "/analytics") {
   490→    return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   491→  }
   492→
   493→  if (segments[0] === "settings") {
   494→    const section = normalizeSettingsSection(segments[1] ? decodePathPart(segments[1]) : "general");
   495→    return { kind: "settings", section, ...suffix };
   496→  }
   497→
   498→  if (segments[0] === "agent" && segments[1]) {
   499→    return { kind: "agent-detail", agentId: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   500→  }
   501→  if (segments[0] === "executor" && segments[1]) {
   502→    return { kind: "executor-detail", executorType: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   503→  }
   504→  if (segments[0] === "skill" && segments[1]) {
   505→    return { kind: "skill-detail", skillId: decodePathPart(segments[1]), agentId: parsed.searchParams.get("agent_id") ?? "", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   506→  }
   507→  if (segments[0] === "mcp-server" && segments[1]) {
   508→    return { kind: "mcp-server-detail", serverName: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   509→  }
   510→  if (segments[0] === "subagent" && segments[1]) {
   511→    return { kind: "subagent-detail", configId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   512→  }
   513→  if (segments[0] === "prompt" && segments[1]) {
   514→    return { kind: "prompt-detail", promptId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   515→  }
   516→  if (segments[0] === "command" && segments[1]) {
   517→    return { kind: "command-detail", commandId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   518→  }
   519→
   520→  if (segments[0] === "workspace" && segments[1] === "page") {
   521→    const workspaceId = parsed.searchParams.get("workspace_id");
   522→    const pageSlug = extractLegacyPageSlug(parsed.searchParams.get("page_path"));
   523→    if (workspaceId && pageSlug) {
   524→      return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   525→    }
   526→  }
   527→
   528→  if (segments[0] === "workspace" && segments[1]) {
   529→    const workspaceId = decodePathPart(segments[1]);
   530→    if (segments.length === 2) return { kind: "workspace-home", workspaceId, ...suffix };
   531→    if (segments[2] === "apps" && !segments[3]) return { kind: "workspace-apps", workspaceId, ...suffix };
   532→    if (segments[2] === "agents" && !segments[3]) return { kind: "workspace-section", workspaceId, section: "agent", ...suffix };
   533→    if (segments[2] === "agent" && segments[3]) return { kind: "workspace-agent-detail", workspaceId, agentId: decodePathPart(segments[3]), ...suffix };
   534→    if (segments[2] === "executor" && segments[3]) return { kind: "workspace-executor-detail", workspaceId, executorType: decodePathPart(segments[3]), ...suffix };
   535→    if (segments[2] === "web") {
   536→      const targetUrl = parsed.searchParams.get("url");
   537→      const title = parsed.searchParams.get("title");
   538→      if (targetUrl && title) {
   539→        return { kind: "workspace-web", workspaceId, url: targetUrl, title, sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined, webId: parsed.searchParams.get("web_id") ?? undefined, hash: parsed.hash || undefined };
   540→      }
   541→    }
   542→    if (segments[2] === "page") {
   543→      const pageSlug = extractWorkspacePageSlug(pathname);
   544→      if (pageSlug) return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   545→    }
   546→    const section = decodePathPart(segments[2]);
   547→    if (isWorkspaceSection(section)) return { kind: "workspace-section", workspaceId, section, ...suffix };
   548→  }
   549→
   550→  if (pathname === "/") return null;
   551→  return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   552→}
