   532→export function useTabNavigation(): TabNavigationActions {
   533→  const activeTabId = useTabStore((state) => state.activeTabId);
   534→  const navigate = useTabStore((state) => state.navigate);
   535→  const goBack = useTabStore((state) => state.goBack);
   536→  const goForward = useTabStore((state) => state.goForward);
   537→  const canGoBackFn = useTabStore((state) => state.canGoBack);
   538→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
   539→  const jumpToHistoryStore = useTabStore((state) => state.jumpToHistory);
   540→
   541→  const goBackInTab = useCallback(() => {
   542→    if (activeTabId && canGoBackFn(activeTabId)) {
   543→      goBack(activeTabId);
   544→    }
   545→  }, [activeTabId, canGoBackFn, goBack]);
   546→
   547→  const goForwardInTab = useCallback(() => {
   548→    if (activeTabId && canGoForwardFn(activeTabId)) {
   549→      goForward(activeTabId);
   550→    }
   551→  }, [activeTabId, canGoForwardFn, goForward]);
   552→
   553→  const jumpToHistory = useCallback(
   554→    (historyIndex: number) => {
